const fs = require('fs');
const A = fs.readFileSync(process.argv[2], 'utf8').split(/\r?\n/);
const B = fs.readFileSync(process.argv[3], 'utf8').split(/\r?\n/);
const CTX = parseInt(process.argv[4] || '6', 10);

// Myers-lite via LCS length table on hashed lines (files ~7k lines; OK)
const n = A.length, m = B.length;
function lcsDiff() {
  // trim common prefix/suffix
  let s = 0;
  while (s < n && s < m && A[s] === B[s]) s++;
  let e = 0;
  while (e < n - s && e < m - s && A[n - 1 - e] === B[m - 1 - e]) e++;
  const a = A.slice(s, n - e), b = B.slice(s, m - e);
  const na = a.length, nb = b.length;
  const dp = new Uint32Array((na + 1) * (nb + 1));
  for (let i = na - 1; i >= 0; i--) {
    for (let j = nb - 1; j >= 0; j--) {
      dp[i * (nb + 1) + j] = a[i] === b[j]
        ? dp[(i + 1) * (nb + 1) + j + 1] + 1
        : Math.max(dp[(i + 1) * (nb + 1) + j], dp[i * (nb + 1) + j + 1]);
    }
  }
  const ops = [];
  for (let i = 0; i < s; i++) ops.push([' ', i, i]);
  let i = 0, j = 0;
  while (i < na && j < nb) {
    if (a[i] === b[j]) { ops.push([' ', s + i, s + j]); i++; j++; }
    else if (dp[(i + 1) * (nb + 1) + j] >= dp[i * (nb + 1) + j + 1]) { ops.push(['-', s + i, -1]); i++; }
    else { ops.push(['+', -1, s + j]); j++; }
  }
  while (i < na) { ops.push(['-', s + i, -1]); i++; }
  while (j < nb) { ops.push(['+', -1, s + j]); j++; }
  for (let k = 0; k < e; k++) ops.push([' ', n - e + k, m - e + k]);
  return ops;
}
const ops = lcsDiff();
// build hunks
const out = [];
out.push('--- linuxdo.user.js');
out.push('+++ linuxdo-codex.user.js');
let idx = 0;
while (idx < ops.length) {
  if (ops[idx][0] === ' ') { idx++; continue; }
  let start = Math.max(0, idx - CTX);
  let end = idx;
  while (end < ops.length) {
    if (ops[end][0] !== ' ') { end++; continue; }
    // count run of context
    let run = end;
    while (run < ops.length && ops[run][0] === ' ') run++;
    if (run >= ops.length || run - end > CTX * 2) { end = Math.min(ops.length, end + CTX); break; }
    end = run;
  }
  const seg = ops.slice(start, end);
  const aStart = seg.find(o => o[1] >= 0)?.[1] ?? 0;
  const bStart = seg.find(o => o[2] >= 0)?.[2] ?? 0;
  const aCount = seg.filter(o => o[0] !== '+').length;
  const bCount = seg.filter(o => o[0] !== '-').length;
  out.push(`@@ -${aStart + 1},${aCount} +${bStart + 1},${bCount} @@`);
  for (const [t, ai, bi] of seg) out.push(t + (t === '-' ? A[ai] : t === '+' ? B[bi] : A[ai]));
  idx = end;
}
fs.writeFileSync(process.argv[5] || 'd.diff', out.join('\n'), 'utf8');
console.log('hunks written, ops=' + ops.length);
"}

